"""Generate the filled Hobbydex icon sprite (24x24, fill currentColor, evenodd holes)."""
import math, sys

def circ(cx, cy, r):
    return f"M{cx-r:.2f} {cy:.2f}a{r:.2f} {r:.2f} 0 1 0 {2*r:.2f} 0a{r:.2f} {r:.2f} 0 1 0 {-2*r:.2f} 0Z"
def ring(cx, cy, r, h):
    return circ(cx, cy, r) + circ(cx, cy, h)
def poly(pts):
    return "M" + "L".join(f"{x:.2f} {y:.2f}" for x, y in pts) + "Z"
def rect(x, y, w, h):
    return poly([(x, y), (x+w, y), (x+w, y+h), (x, y+h)])
def rrect(x, y, w, h, r):
    return (f"M{x+r} {y}h{w-2*r}a{r} {r} 0 0 1 {r} {r}v{h-2*r}a{r} {r} 0 0 1 {-r} {r}h{-(w-2*r)}"
            f"a{r} {r} 0 0 1 {-r} {-r}v{-(h-2*r)}a{r} {r} 0 0 1 {r} {-r}Z")
def cog(cx, cy, n, ro, ri, tw=0.5):
    pts = []
    for i in range(n):
        a = 2*math.pi*i/n; h = math.pi/n*tw
        for ang, r in ((a-h*1.5, ri), (a-h, ro), (a+h, ro), (a+h*1.5, ri)):
            pts.append((cx+r*math.sin(ang), cy-r*math.cos(ang)))
    return poly(pts)
def wheels(*ws):   # (cx, cy, r): a tyre with a hub hole
    return "".join(ring(cx, cy, r, r*0.38) for cx, cy, r in ws)
def rot(d, deg, cx=12, cy=12):
    return (d, f' transform="rotate({deg} {cx} {cy})"')

